```typescript
type OrderState = 'created' | 'paid' | 'shipped' | 'delivered' | 'cancelled' | 'refunded';

const validTransitions: Record<OrderState, OrderState[]> = {
  created:   ['paid', 'cancelled'],
  paid:      ['shipped', 'refunded'],
  shipped:   ['delivered', 'cancelled'],
  delivered: ['refunded'],
  cancelled: [],
  refunded:  []
};

class OrderStateMachine {
  private state: OrderState = 'created';

  transition(nextState: OrderState): void {
    if (!validTransitions[this.state].includes(nextState)) {
      throw new Error(`Invalid transition: ${this.state} → ${nextState}`);
    }
    this.state = nextState;
  }

  canTransition(nextState: OrderState): boolean {
    return validTransitions[this.state].includes(nextState);
  }

  getState(): OrderState {
    return this.state;
  }
}

// Usage
const order = new OrderStateMachine();
order.transition('paid');      // ✓ created → paid
order.transition('shipped');   // ✓ paid → shipped
order.transition('delivered'); // ✓ shipped → delivered
order.transition('paid');      // ✗ throws: Invalid transition: delivered → paid
```

Flow: `created` → `paid`/`cancelled`. `paid` → `shipped`/`refunded`. `shipped` → `delivered`/`cancelled`. `delivered` → `refunded`. `cancelled` & `refunded` terminal. Invalid transitions throw; query `canTransition()` before acting to avoid exceptions.
